/* All records below are explicit demonstration fixtures. No production data or external API. */
'use strict';
const E=window.Accounting,SCHEMA=window.WORKBOOK_SCHEMA,KEY='salah-preview-full-cycle-v1';
const $=s=>document.querySelector(s),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format((n||0)/100),num=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n||0);
const stateLabels={draft:'مسودة',review:'قيد المراجعة',approved:'معتمد',posted:'مرحّل',reversed:'معكوس'},roleLabels={owner:'المالك',accountant:'المحاسب',reviewer:'المراجع',viewer:'مشاهد'};
const groups=[['الرئيسية والرقابة','◈',[0,37,43]],['الحسابات','▤',[15,16,17,40,2]],['المبيعات والمشتريات','⇄',[18,19,10,20,21,11]],['الخزينة والبنوك','▥',[22,23,24,25]],['المخزون والمواقع','▦',[26,27,12,41]],['الأصول والمشروعات','◇',[29,30,31,13,44,45,46,47,48,49,50,51]],['الموظفون والرواتب','♙',[32,33,14]],['التخطيط والتحليل','⌁',[34,8,35,9,42,7]],['التقارير المالية','▧',[3,4,5,6]],['الإعدادات والسياسات','⚙',[1,28,36,38,39]]];
const masterRoute={15:'accounts',18:'customers',20:'vendors',24:'banks',26:'items',28:'centers',32:'employees',34:'budget',35:'cashplan',41:'locations',44:'projects',25:'reconciliations'};
const txRoute={16:['opening'],17:Object.keys(E.types),19:['sales'],21:['purchase'],22:['receipt','payment','settlement','settlementbatch'],27:['stockin','stockout','stocktransfer','stockclose'],29:['asset'],30:['asset','depreciation','disposal'],31:['depreciation'],33:['payroll','salarypay','insurancepay'],45:['cipcost'],46:['ciptransfer'],47:['impairment'],50:['cipcost','ciptransfer','impairment','amort']};
let S,role='owner',route='home',lastFocus=null,modalSubmit=null,tableQuery='',tableStatus='all',showZero=false,selectedJourney=0,selectedStep=0,lastRows=[],lastHeaders=[],inTour=false;
try{const raw=localStorage.getItem(KEY);S=window.SecureStore?.enabled?E.initial(ACCOUNT_SEED):(raw?JSON.parse(raw):window.PreviewModel.create());if(S.version!==1||!Array.isArray(S.docs))throw Error('version');}catch{S=window.PreviewModel.create();}
function persist(){if(window.SecureStore?.enabled){window.SecureStore.status();return;}try{localStorage.setItem(KEY,JSON.stringify(S));$('#saveStatus').textContent='● محفوظ محليًا';}catch{$('#saveStatus').textContent='الحفظ غير متاح · صدّر نسخة';}window.__LAB_STATE=S;}
function toast(text,error=false){const el=$('#toast');el.textContent=text;el.className='show'+(error?' error':'');clearTimeout(toast.t);toast.t=setTimeout(()=>el.className='',6000);}
function attempt(fn){try{fn();persist();return true;}catch(e){toast(e.message,true);return false;}}
const moneyCell=n=>`<span class="num">${fmt(n)}</span>`;
const b=(text,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${h(id)}">${text}</button>`;
const badge=status=>`<span class="badge ${status}">${h(stateLabels[status]||status)}</span>`;
const note=(text,type='')=>`<div class="notice ${type}">${text}</div>`;
const kpi=(label,value,sub)=>`<div class="kpi"><span class="label">${label}</span><strong class="value">${value}</strong><small>${sub||'جنيه مصري · بيانات تجريبية'}</small></div>`;
function heading(title,desc,actions='',over='مساحة العمل'){return `<div class="page-heading"><div><div class="overline">${over}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>`;}
function table(headers,rows,emptyText='لا توجد سجلات حتى الآن',emptyAction=''){lastHeaders=headers;lastRows=rows;return `<div class="table-wrap"><table><thead><tr>${headers.map((x,i)=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map((c,i)=>`<td${typeof c==='number'?' class="number"':''}>${typeof c==='number'?fmt(c):c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="empty"><div class="empty-icon">▤</div><h3>${emptyText}</h3><p>ابدأ بسجل تجريبي، أو استخدم الدورة الموجهة لتعرف الخطوة التالية.</p>${emptyAction}</div></td></tr>`}</tbody></table></div>`;}
function context(){return `<div class="report-context"><span>الفترة: <b class="num">${h(S.view.from)} → ${h(S.view.to)}</b></span><span>العملة: EGP</span><span>أثر القيود المرحّلة والعكس بتاريخها فقط</span></div>`;}
function toolbar(types=false){return `<div class="table-toolbar"><div class="toolbar-start"><input id="tableSearch" type="search" placeholder="بحث في السجلات…" aria-label="بحث في السجلات" value="${h(tableQuery)}">${types?`<select id="statusFilter" aria-label="فلترة الحالة"><option value="all">كل الحالات</option>${Object.entries(stateLabels).map(([v,t])=>`<option value="${v}" ${tableStatus===v?'selected':''}>${t}</option>`).join('')}</select>`:''}</div><div class="toolbar-end">${b('↓ تصدير التقرير','report-export','','small')}${b('طباعة','print','','small')}</div></div>`;}
function schemaDetails(i){const sc=SCHEMA[i];return `<details class="meta-details"><summary>مرجع الإكسل · الورقة ${i+1} من 52 · ${h(sc.name)}</summary><p>هذه شاشة تجربة مرتبطة بنطاق الورقة. حقول المرجع أدناه لا تعني أن كل معالجة متخصصة أصبحت جاهزة للإنتاج. الحقول الأساسية في النماذج، والباقي يظهر في التفاصيل والسياسات.</p>${sc.tables.map(t=>`<b>${h(t.name)}</b><div class="field-chips">${t.columns.map(c=>`<span>${h(c)}</span>`).join('')}</div>`).join('')||'<p>تقرير أو دليل مستند إلى البيانات المشتركة.</p>'}</details>`;}
function nav(){const q=$('#navSearch').value.trim();$('#navigation').innerHTML=groups.map(([name,icon,ids])=>{const filtered=ids.filter(i=>!q||SCHEMA[i].name.includes(q));if(!filtered.length)return '';const active=ids.includes(Number(route));return `<details ${active||q?'open':''}><summary><span class="nav-icon">${icon}</span>${name}</summary>${filtered.map(i=>`<button class="nav-link ${String(route)===String(i)?'active':''}" data-action="route" data-id="${i}" ${String(route)===String(i)?'aria-current="page"':''}>${h(SCHEMA[i].name)}<span class="sheet-no">${i+1}</span></button>`).join('')}</details>`;}).join('');}
function go(r){route=String(r);tableQuery='';tableStatus='all';document.body.classList.remove('nav-open');$('#menuToggle').setAttribute('aria-expanded','false');history.replaceState(null,'','#'+(route==='home'?'home':route));render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
function render(){nav();$('#companyName').textContent=S.config.company;$('#fromDate').value=S.view.from;$('#toDate').value=S.view.to;$('#periodBadge').textContent=S.closed.some(p=>p.from<=S.view.from&&p.to>=S.view.to)?'فترة مقفلة':'فترة مفتوحة';$('#breadcrumb').textContent=route==='home'?'مساحة العمل / نظرة عامة':route==='tour'?'الدورة الكاملة / تجربة موجهة':route==='map'?'المشروع / خريطة الـ52 ورقة':`مساحة العمل / ${({access:'إدارة الوصول',excel:'Excel والبيانات','tax-report':'تقرير الضرائب',subscriptions:'الاشتراكات والخدمات الرقمية'})[route]||SCHEMA[Number(route)]?.name||'المساعدة'}`;let html;if(route==='home'||route==='0')html=home();else if(route==='tour')html=tourPage();else if(route==='map'||route==='43')html=mapPage();else if(route==='help')html=helpPage();else if(route==='excel')html=excelPage();else if(route==='access')html=accessPage();else if(SCHEMA[Number(route)])html=sheetPage(Number(route));else html=home();$('#main').innerHTML=html;persist();if(route==='access')queueMicrotask(()=>window.AccessUI?.show().catch(e=>{const box=document.getElementById('accessWorkspacePage');if(box)box.textContent=e.message;}));}
function home(){const f=E.financial(S,S.view.to,S.view.from),pending=S.docs.filter(d=>['draft','review','approved'].includes(d.status));return heading('سجّل العملية مرة واحدة.','اختار نوع العملية. الضريبة والقيد ورصيد الطرف والتقارير بيتحدثوا من نفس المستند.',b('سجّل عملية','new-choice','','primary'))+panel('هتسجل إيه؟',`<div class="operation-grid">${[['sales','بيع لعميل','بنود الفاتورة وضريبة كل بند ثم قيد العميل والإيراد'],['purchase','شراء أو مصروف','مورد أو موقع، وضريبة كل بند وحساب التكلفة'],['receipt','تحصيل من عميل','اربط التحصيل بالفاتورة والخصم والمتبقي'],['payment','سداد لمورد','دفعة لواحدة أو عدة فواتير مع فصل النقد والضريبة'],['journal','قيد يدوي أو تسوية','مدين ودائن وبيانات الضريبة في السطر المناسب']].map(([id,label,desc])=>`<button type="button" class="module-card" data-action="unified-operation" data-id="${id}"><b>${label}</b><p>${desc}</p></button>`).join('')}</div>`)+note('المسار واحد: بيانات العملية ← الضريبة ← معاينة القيد ← مراجعة واعتماد وترحيل ← الأرصدة والتقارير.','neutral')+`<div class="kpis">${kpi('النقدية والبنوك',fmt(f.cash),'رصيد حتى '+S.view.to)}${kpi('مستحق لدى العملاء',fmt(f.ar),'من نفس القيود المرحّلة')}${kpi('مستحق للموردين',fmt(f.ap),'من نفس القيود المرحّلة')}${kpi('مستندات تحتاج إجراء',pending.length,'المسودة لا تغير الأرصدة')}</div>`+panel('آخر العمليات',docTable(S.docs.filter(d=>!d.reverses).slice(-6)),b('كل اليومية','route','17','text-btn'))+panel('الخطوة اللي بعدها',`<div class="inline-actions">${b('شرح الدورة خطوة بخطوة','tour')}${b('كل الأقسام والتقارير','map')}${b('Excel والبيانات','route','excel')}${b('إدارة الوصول','route','access')}</div>`);}
function excelPage(){return heading('Excel والبيانات','اختار الملف والورقة، اربط الأعمدة، وافحص المعاينة قبل إضافة البيانات.',b('استيراد Excel أو CSV','file-import','','primary'))+panel('إدخال البيانات من Excel',`<ol class="check-list"><li>اختار ملف Excel، ولو فيه أكثر من ورقة اختار الورقة المطلوبة.</li><li>حدد نوع البيانات: عملاء أو موردين أو أصناف أو موظفين أو قيود يدوية.</li><li>اربط الأعمدة وراجع المعاينة. القيود تدخل مسودات للمراجعة.</li></ol>`)+note('استيراد البيانات يقرأ الجدول المختار؛ لا ينفذ معادلات الملف ولا يحوّل كل منطق ملف محاسبي تلقائيًا. ارفع ملفك هنا في المحادثة لمراجعة بنيته وربط أوراقه إذا كان مختلفًا.','neutral')+panel('تصدير واسترجاع',`<p>تصدير البيانات والتقارير حسب الفترة؛ ونسخة JSON لاسترجاع بيانات التطبيق بعد فحصها.</p><div class="inline-actions">${b('تصدير Excel والتقارير','report-export')}${b('نسخة بيانات JSON','export-json')}${b('استرجاع نسخة JSON','import-json')}</div>`);}
function accessPage(){return heading('إدارة الوصول','كل عضو يدخل بحسابه، وصلاحيته يحددها المالك وتُراجع على الخادم.')+panel('الأعضاء والدعوات',`<div id="accessWorkspacePage" role="status">جاري فتح إدارة الوصول…</div>`);}

function docTable(ds){return table(['المستند','التاريخ','النوع','البيان','القيمة / الكمية','الحالة'],ds.map(d=>[`<button class="table-btn" data-action="doc" data-id="${h(d.id)}">${h(d.id)}</button>`,`<span class="num">${h(d.date)}</span>`,h(E.types[d.type]),`<span title="${h(d.description)}">${h(d.description).slice(0,50)}</span>`,['stockin','stockout','stocktransfer'].includes(d.type)?`${num(d.qty)} قطعة`:fmt(docAmount(d)),badge(d.status)]),'ابدأ أول مستند',b('ابدأ دورة موجهة','tour','','small'));}
function docAmount(d){try{if(['sales','purchase'].includes(d.type)&&d.invoiceLines)return E.invoiceTotals(S,d).payable;if(d.type==='settlementbatch')return d.settlementSnapshot?.settled||E.settlementBatchTotals(S,d).settled;if(d.type==='settlement')return d.settlementSnapshot?.settled||E.settlementTotals(S,d).settled;if(d.type==='ciptransfer')return E.money(d.gross||0);if(d.type==='impairment')return E.money(d.loss||0);if(d.type==='payroll'){try{return E.payroll(S,d).cost;}catch{return 0;}}if(d.type==='disposal')return E.money(d.proceeds||0);if(d.type==='journal')return E.sum(d.journal||[],l=>l.debit);return E.money(d.amount||0);}catch{return 0;}}
function txPage(i,types){const selected=S.docs.filter(d=>types.includes(d.type)&&!d.reverses&&(tableStatus==='all'||d.status===tableStatus)&&JSON.stringify(d).toLowerCase().includes(tableQuery.toLowerCase()));let tips='احفظ المسودة، أرسلها للمراجعة، اعتمدها ثم رحّلها. التقارير لا تتأثر بمجرد الحفظ.';if(i===27)tips='الحركات هنا تشغيلية لكل صنف ومخزن. تسوية المخزون الدورية عملية مالية مستقلة، بعد مطابقة قيمة الوارد مع المشتريات.';if(i===33)tips='الأجر والتأمينات من إعدادات المثال؛ الضريبة المعتمدة إدخال للمحاكاة. لا يُعد هذا إقرارًا أو محرك رواتب قانونيًا لكل الحالات.';if(i===45)tips='حدد هل التكلفة مصروف أم مؤهلة للرسملة. تظهر شروط التطوير ومراجع الإثبات، ويمنع تكرار تحميل بند المصدر.';if(i===46)tips='التحويل ينقل التكلفة الإجمالية ومجمع الاضمحلال معًا. الإطفاء يُسجل منفصلًا من الجاهزية الفعلية.';return heading(h(SCHEMA[i].name),'مستندات مترابطة · بحث ومراجعة وترحيل وتتبع الأثر',b('＋ إضافة','new-tx',types.length===1?types[0]:types.join(','),'primary'))+note(tips)+toolbar(true)+docTable(selected)+schemaDetails(i);}
function sheetPage(i){if(masterRoute[i])return masterPage(i,masterRoute[i]);if(txRoute[i])return txPage(i,txRoute[i]);if(i===23)return allocationsPage();if(i===36)return periodsPage();if(i===37)return controlPage();if(i===1)return settingsPage();if([38,39,51].includes(i))return helpPage(i);return reportPage(i);}
function mapPage(){return heading('الـ52 ورقة، في مكان واحد.','كل ورقة لها مسار هنا. التقارير تحسب من العمليات التجريبية، والأدلة تشرح حدود المعالجة.',b('ابدأ الدورة الكاملة','tour','','primary'),'خريطة التغطية / EXCEL → APP')+note('التغطية تعني وجود شاشة أو تقرير أو دليل تفاعلي لكل ورقة؛ لا تعني تنفيذ كل المتطلبات المحاسبية أو الأمنية للإنتاج.','neutral')+groups.map(([name,icon,ids])=>`<h2 class="section-title">${icon} ${name}</h2><div class="coverage">${ids.map(i=>`<button data-action="route" data-id="${i}"><span>${String(i+1).padStart(2,'0')}</span><span><b>${h(SCHEMA[i].name)}</b><small>${masterRoute[i]?'إضافة وتعديل سجل':txRoute[i]?'مستند ومراجعة وترحيل':[38,39,51].includes(i)?'دليل داخل السياق':i===23?'توزيع دفعة على فواتير':i===36?'محاكاة أدوار وإقفال':'عرض تفاعلي وحساب من البيانات'}</small></span></button>`).join('')}</div>`).join('');}
function masterPage(i,key){const rows=S[key].filter(x=>JSON.stringify(x).toLowerCase().includes(tableQuery.toLowerCase()));const actions=b('＋ إضافة سجل','new-master',key,'primary');let heads=['الكود','الاسم','تفاصيل','إجراء'];let rs=rows.map(x=>[h(x.id),h(x.name||x.account||x.date),masterSummary(key,x),b('عرض وتعديل','edit-master',key+'|'+x.id,'small')]);if(key==='accounts')rs=rows.map(x=>[`<span class="num">${h(x.id)}</span>`,h(x.name),`${h(x.type)} · ${x.postable?'فرعي قابل للترحيل':'رئيسي'}`,b('عرض وتعديل','edit-master',key+'|'+x.id,'small')]);return heading(h(SCHEMA[i].name),'سجل موحّد تستخدمه المستندات والتقارير. افتح السجل لتجربة التعديل.',actions)+(key==='projects'?note('مشروع الشركة يحتاج إثبات السيطرة والشروط الستة للتطوير. أعمال العملاء واشتراكات SaaS لا تُصنف تلقائيًا أصلًا مملوكًا.'):key==='reconciliations'?note('فرق المطابقة = الدفتر المعدل − الكشف المعدل. بنود الكشف غير المسجلة تحتاج قيدًا مستقلًا؛ لا تختفي لمجرد إدخال المطابقة.'):key==='budget'?note('أدخل الموازنة بالقيمة الطبيعية للحساب. الإيراد المخطط يظهر موجبًا في مقارنة الإدارة.'):context())+toolbar()+table(heads,rs)+schemaDetails(i);}
function masterSummary(key,x){switch(key){case 'customers':case 'vendors':return `${num(x.days)} يوم سداد`;case 'employees':return `أجر ${fmt(E.money(x.salary||0))} · تأميني ${fmt(E.money(x.insured||0))}`;case 'items':return `${h(x.unit)} · حد طلب ${num(x.min)}`;case 'locations':return h(x.type);case 'banks':return `${h(x.account)} · ${fmt(E.balance(S,x.account,S.view.to))}`;case 'projects':{const c=E.cip(S,x.id,S.view.to);return `${h(x.kind)} · تحت التنفيذ ${fmt(c.balance)} · جاهز ${fmt(c.ready)}`;}case 'budget':return `${fmt(E.money(x.amount))} · ${h(x.date)}`;case 'cashplan':return `تحصيل ${fmt(E.money(x.incoming||0))} / دفع ${fmt(E.money(x.outgoing||0))}`;case 'reconciliations':return `فرق ${fmt(recon(x).diff)}`;default:return 'سجل مرجعي';}}
function recon(x){const book=E.balance(S,x.account||'112101',x.date||S.view.to),bank=E.money(x.statement||0),inTransit=E.money(x.deposits||0),checks=E.money(x.checks||0),fees=E.money(x.fees||0),interest=E.money(x.interest||0);return {book,bank,adjustedBook:book-fees+interest,adjustedBank:bank+inTransit-checks,diff:book-fees+interest-bank-inTransit+checks};}
function allocationsPage(){const derived=E.settlementEntries(S,S.view.to).filter(d=>d.date>=S.view.from);const rs=derived.map(d=>{const v=d.settlementSnapshot||E.settlementTotals(S,d);return [docLink(d.id),docLink(d.invoice),h(d.date),v.settled,v.wht,v.cash];});const old=S.allocations.filter(a=>JSON.stringify(a).includes(tableQuery)).map(a=>[h(a.id),docLink(a.payment),docLink(a.invoice),a.amount,h(a.date),b('إلغاء التخصيص','unallocate',a.id,'small danger')]);return heading('التحصيل والسداد المرتبط بالفواتير','كل صف يوضح المستند والفاتورة والمبلغ المسوّى والخصم والنقد، من نفس قيد السداد.',b('تحصيل من عميل','unified-operation','receipt','primary')+b('سداد لمورد','unified-operation','payment'))+context()+toolbar()+table(['السند','الفاتورة','التاريخ','المبلغ المسوّى','الخصم الضريبي','النقد الفعلي'],rs)+`<details class="meta-details"><summary>تخصيص سند سابق أو دفعة مقدمة</summary><p>التخصيصات القديمة محفوظة هنا. الفواتير المفصلة تستخدم السداد المرتبط لحساب الضريبة دون قيد مكرر.</p>${b('تخصيص سند سابق','allocate')}${table(['التخصيص','السند','الفاتورة','المبلغ','التاريخ','إجراء'],old)}</details>`+schemaDetails(23);}

