function controls(){const f=E.financial(S,S.view.to,S.view.from);const stockNegative=S.items.some(i=>S.locations.some(w=>E.stock(S,i.id,w.id,S.view.to)<0));const arOpen=E.sum(E.posted(S,'sales',S.view.to),d=>E.remaining(S,d.id,S.view.to));const apOpen=E.sum(E.posted(S,'purchase',S.view.to),d=>E.remaining(S,d.id,S.view.to));const receiptFree=E.sum(E.posted(S,'receipt',S.view.to),d=>E.money(d.amount)-E.sum(S.allocations.filter(a=>a.payment===d.id&&a.date<=S.view.to),a=>a.amount));const paymentFree=E.sum(E.posted(S,'payment',S.view.to),d=>E.money(d.amount)-E.sum(S.allocations.filter(a=>a.payment===d.id&&a.date<=S.view.to),a=>a.amount));const manualIds=new Set(S.docs.filter(d=>d.type==='journal'&&(!d.reverses||S.docs.find(o=>o.id===d.reverses)?.type==='journal')).map(d=>d.id)),manualRows=E.journalRows(S,S.view.to).filter(l=>manualIds.has(l.id)),arAdjust=E.sum(manualRows.filter(l=>l.account==='121000'&&S.customers.some(p=>p.id===l.party)),l=>l.debit-l.credit),apAdjust=-E.sum(manualRows.filter(l=>l.account==='211000'&&S.vendors.some(p=>p.id===l.party)),l=>l.debit-l.credit);const cipSub=E.sum(S.projects,p=>E.cip(S,p.id,S.view.to).balance),cipGl=E.balance(S,'154000',S.view.to)+E.balance(S,'155000',S.view.to)+E.balance(S,'159300',S.view.to)+E.balance(S,'159400',S.view.to);return [['توازن المركز المالي',f.balance,4,'الأصول = الالتزامات + حقوق الملكية + النتيجة المتراكمة'],['مطابقة العملاء بعد الدفعات غير المخصصة',arOpen-receiptFree+arAdjust-f.ar,10,'متبقي الفواتير ناقص التحصيل غير المخصص'],['مطابقة الموردين بعد الدفعات غير المخصصة',apOpen-paymentFree+apAdjust-f.ap,11,'متبقي الفواتير ناقص الدفعات غير المخصصة'],['مطابقة مشروعات تحت التنفيذ',cipSub-cipGl,48,'دفتر المشروعات مع حسابات التنفيذ والمجمعات'],['المخزون غير سالب',stockNegative?100:0,12,'لكل صنف ومخزن حتى تاريخ التقرير']];}
